    function getCCColor(buffs) {
        if (buffs.has(101)) return ne.deepFreezeColor;
        if (buffs.has(91)) return ne.agonizeColor;
        if (buffs.has(88)) return ne.stunColor;
        if (buffs.has(119)) return ne.blindColor;
        if (buffs.has(121)) return ne.relColor;
        if (buffs.has(69)) return ne.chillColor;
        return null;
    }

    function hexParts(hex) {
        return [parseInt(hex.slice(1, 3), 16), parseInt(hex.slice(3, 5), 16), parseInt(hex.slice(5, 7), 16)];
    }

    function hexToRgba(hex, a) {
        let [r, h, b] = hexParts(hex);
        return `rgba(${r},${h},${b},${a})`;
    }

    function flashColor(hex, speed, intensity) {
        let pulse = (Math.sin(T.smoothtime * Math.PI * speed) + 1) * 1.2;
        let [r, h, b] = hexParts(hex);
        return `rgb(${Math.round(r*(1-pulse*intensity))},${Math.round(h*(1-pulse*intensity))},${Math.round(b*(1-pulse*intensity))})`;
    }

